#!/usr/bin/env bash
# Builds the engine for iOS (docs/phase3-design.md §2):
#
#   scripts/build-ios.sh             device, simulator and macOS slices
#   scripts/build-ios.sh --sim-only  simulator and macOS only (everyday loop)
#
# 1. ephemeris-ffi in release for each slice (static libraries).
# 2. The Swift bindings, generated by uniffi-bindgen from the macOS dylib.
# 3. ios/EphemerisKit/EphemerisFFI.xcframework from the libraries and the
#    generated header (SwiftPM only takes a binary target inside the package).
# 4. The generated Swift file and the golden files copied into EphemerisKit.
#
# Everything it writes is gitignored. The macOS slice lets `swift test` run
# the FFI on this Mac without a simulator. Needs Xcode and the Rust targets
# aarch64-apple-ios, aarch64-apple-ios-sim (rustup target add ...).
set -euo pipefail
cd "$(dirname "$0")/.."

sim_only=0
case "${1:-}" in
  "") ;;
  --sim-only) sim_only=1 ;;
  *) echo "usage: $0 [--sim-only]" >&2; exit 2 ;;
esac

# Match the app's deployment targets, so the linker does not warn.
export IPHONEOS_DEPLOYMENT_TARGET=17.0
export MACOSX_DEPLOYMENT_TARGET=14.0

KIT=ios/EphemerisKit
GEN=ios/build/generated
XCF=$KIT/EphemerisFFI.xcframework
GOLDEN=crates/ephemeris-wasm/tests/golden

targets=(aarch64-apple-ios-sim aarch64-apple-darwin)
[ "$sim_only" = 1 ] || targets=(aarch64-apple-ios "${targets[@]}")

# 1. Static libraries. On iOS only the staticlib is needed; on macOS the
#    cdylib too, for uniffi-bindgen to read the interface from.
for t in "${targets[@]}"; do
  echo "== ephemeris-ffi for $t"
  if [ "$t" = aarch64-apple-darwin ]; then
    cargo build --release -p ephemeris-ffi --lib --target "$t"
  else
    cargo rustc --release -p ephemeris-ffi --lib --target "$t" --crate-type staticlib
  fi
done

# 2. Swift bindings, header and module map.
echo "== Swift bindings"
cargo build -p ephemeris-ffi --features bindgen --bin uniffi-bindgen
rm -rf "$GEN"
target/debug/uniffi-bindgen generate \
  --library target/aarch64-apple-darwin/release/libephemeris_ffi.dylib \
  --language swift --out-dir "$GEN"
mkdir -p "$GEN/include"
cp "$GEN/ephemeris_ffiFFI.h" "$GEN/include/"
cp "$GEN/ephemeris_ffiFFI.modulemap" "$GEN/include/module.modulemap"

# 3. The XCFramework.
echo "== $XCF"
args=()
for t in "${targets[@]}"; do
  args+=(-library "target/$t/release/libephemeris_ffi.a" -headers "$GEN/include")
done
rm -rf "$XCF"
xcodebuild -create-xcframework "${args[@]}" -output "$XCF" >/dev/null

# 4. Generated Swift and golden files into the package.
mkdir -p "$KIT/Sources/EphemerisKit/Generated" "$KIT/Tests/EphemerisKitTests/Golden"
cp "$GEN/ephemeris_ffi.swift" "$KIT/Sources/EphemerisKit/Generated/"
cp "$GOLDEN"/{feed.json,report.json,report-all-fields.json,simulate-options.json,forecast-options.json} \
  "$KIT/Tests/EphemerisKitTests/Golden/"

echo "== done: $XCF ($(du -sh "$XCF" | cut -f1))"
